(function(E){ const x = E["hr-m4"] = E["hr-m4"] || {units:{}}; x.units["hr-cp-4"] = {"writing":{"id":"c-hr-cp-4-w","title":{"en":"The leave policy, plainly","tr":"İzin politikası, sade dille","fa":"آیین‌نامه‌ی مرخصی به زبان ساده"},"course":"hr","unit":"hr-cp-4","portfolio":null,"type":"writing","difficulty":"hard","prompt":{"en":"Explain this leave policy in plain English to a new driver (60-90 words, \"you\", short sentences): \"Requests for annual leave must be submitted via the HR portal no fewer than fourteen (14) days in advance and are subject to line manager approval, which shall not be unreasonably withheld. Leave may not be carried over into the subsequent calendar year save in exceptional circumstances.\"","tr":"Bu izin politikasını yeni bir sürücüye sade İngilizceyle açıkla (60-90 kelime, \"you\", kısa cümleler): \"Requests for annual leave must be submitted via the HR portal no fewer than fourteen (14) days in advance and are subject to line manager approval, which shall not be unreasonably withheld. Leave may not be carried over into the subsequent calendar year save in exceptional circumstances.\"","fa":"این آیین‌نامه‌ی مرخصی را برای یک راننده‌ی تازه‌وارد به انگلیسی ساده توضیح بده (۶۰ تا ۹۰ کلمه، با خطاب you و جمله‌های کوتاه): «⁨Requests for annual leave must be submitted via the HR portal no fewer than fourteen (14) days in advance and are subject to line manager approval, which shall not be unreasonably withheld. Leave may not be carried over into the subsequent calendar year save in exceptional circumstances.⁩»"},"model":"If you want to take holiday, ask on the HR portal at least 14 days before. Your manager needs to approve it. They cannot say no without a good reason. Please use all your holiday days in the same year, because you usually cannot move them to next year. If something very unusual happens, talk to HR and we will see what we can do. If you are not sure how to use the portal, your buddy can show you.","frame":"If you want to ___, ask ___ at least ___ before. Your manager needs to ___. They cannot ___. Please ___, because you usually cannot ___. If something very unusual happens, ___.","words":[{"word":"if you"},{"word":"need"},{"word":"before"}],"minWords":60,"minSentences":6,"rubric":["Task done: how to ask, how early, approval, the carry-over rule, the exception","Organised: in the order the reader needs it","Language: if + present; need to / cannot; no unexplained legal words","Tone: friendly, clear, not threatening"],"rubricI18n":{"tr":["Görev: nasıl istenir, ne kadar önceden, onay, devretme kuralı, istisna","Düzen: okurun ihtiyaç duyduğu sırayla","Dil: if + present; need to / cannot; açıklanmamış hukuki terim yok","Üslup: samimi, net, tehditkâr değil"],"fa":["کامل بودن کار: چطور درخواست بدهند، چقدر زودتر، تأیید، قانون انتقال مرخصی به سال بعد، استثنا","نظم: به همان ترتیبی که خواننده لازم دارد","زبان: if با حال ساده؛ need to / cannot؛ بدون اصطلاح حقوقیِ توضیح‌نداده","لحن: دوستانه، روشن، نه تهدیدآمیز"]},"parts":[{"t":{"en":"How to ask, and how early","tr":"Nasıl ve ne kadar önceden isteneceği","fa":"اینکه چطور و چقدر زودتر درخواست بدهد"},"find":["portal","at least","before"],"sample":"on the HR portal, at least 14 days before"},{"t":{"en":"Who approves","tr":"Kimin onaylayacağı","fa":"اینکه چه کسی تأیید می‌کند"},"find":["approve","manager"],"sample":"your manager approves; no only with a good reason"},{"t":{"en":"The carry-over rule","tr":"İzin devri kuralı","fa":"قانون انتقال مرخصی"},"find":["same year","next year"],"sample":"use the days in the same year"},{"t":{"en":"The exception","tr":"İstisna","fa":"استثنا"},"find":["unusual","talk to hr"],"sample":"something very unusual: talk to HR"}]},"speaking":{"id":"hr-cp-4-sp","course":"hr","unit":"hr-cp-4","rounds":[90,60],"topic":{"en":"Summarising Ece's Complaint","tr":"Ece'nin Şikâyetini Özetlemek","fa":"خلاصه کردن شکایت اجه"},"warmup":{"en":"Read Ece's words: \"My schedule changed three times this month, each time with one day's notice. I have two children. I can't plan anything. The job ad said schedules would be shared two weeks in advance.\"","tr":"Ece'nin sözlerini oku: \"Programım bu ay üç kez değişti, her seferinde bir gün önceden haber verildi. İki çocuğum var. Hiçbir şey planlayamıyorum. İş ilanında programların iki hafta önceden paylaşılacağı yazıyordu.\"","fa":"حرف‌های اجه را بخوان: «برنامه‌ی کاری‌ام این ماه سه بار عوض شد، هر بار فقط یک روز قبل خبر دادند. دو تا بچه دارم. نمی‌توانم برای هیچ چیز برنامه بریزم. توی آگهی استخدام نوشته بود برنامه‌ها دو هفته زودتر اعلام می‌شود.»"},"questions":[{"en":"Summarise her feelings in one sentence. Use \"It sounds like...\" or \"That sounds...\".","tr":"Duygularını tek cümleyle özetle. \"It sounds like...\" ya da \"That sounds...\" kullan.","fa":"احساس اجه را در یک جمله خلاصه کن. از «⁨It sounds like...⁩» یا «⁨That sounds...⁩» استفاده کن."},{"en":"Summarise her reasons: \"So what you're saying is...\"","tr":"Sebeplerini özetle: \"So what you're saying is...\"","fa":"دلیل‌هایش را خلاصه کن: «⁨So what you're saying is...⁩»"},{"en":"Agree one next step with a date.","tr":"Tarihli bir sonraki adım üzerinde anlaş.","fa":"روی یک قدم بعدی و یک تاریخ مشخص با او توافق کن."}],"followups":[{"en":"Say it out loud in 90 seconds, then in 60.","tr":"Yüksek sesle söyle: önce 90 saniyede, sonra 60 saniyede.","fa":"پاسخت را با صدای بلند بگو: یک بار در ۹۰ ثانیه و بعد در ۶۰ ثانیه."}],"expressions":[{"phrase":"Can I check I've understood?","meaning":{"en":"Opens the summary.","tr":"Özeti başlatır.","fa":"خلاصه کردن را شروع می‌کند."}},{"phrase":"That sounds really stressful.","meaning":{"en":"Names the feeling.","tr":"Duyguyu adlandırır.","fa":"احساس طرف را نام می‌برد."}},{"phrase":"Here's what I'll do, and by when.","meaning":{"en":"Agrees a next step.","tr":"Bir sonraki adımı kararlaştırır.","fa":"قدم بعدی را با زمانش مشخص می‌کند."}}]},"perspective":{"id":"c-hr-cp-4-p","title":{"en":"Ece, who believed the ad","tr":"İlana inanan Ece","fa":"اجه که به آگهی اعتماد کرد"},"course":"hr","unit":"hr-cp-4","type":"perspective","minSentences":3,"prompt":{"en":"You are Ece, the driver who read the job ad in lesson 2.2 and believed it. Write 3 sentences in first person: what did the ad promise you, what happened, and what would rebuild your trust?","tr":"2.2. dersteki iş ilanını okuyup ona inanan sürücü Ece'sin. Birinci tekil şahısla 3 cümle yaz: ilan sana ne vaat etti, ne oldu ve güvenini yeniden ne kazandırır?","fa":"تو اجه هستی، همان راننده‌ای که آگهی استخدام درس ۲.۲ را خواند و باورش کرد. از زبان خودت سه جمله بنویس: آن آگهی چه قولی به تو داده بود، چه شد و چه چیزی می‌تواند اعتمادت را دوباره برگرداند؟"}},"exit":{"id":"c-hr-cp-4-x","course":"hr","unit":"hr-cp-4","type":"exit","note":"8 spaced items across modules 1-4.","items":[{"from":"hr-1-2","kind":"blank","prompt":"Would you mind ___ the new rota to all drivers?","options":["sending","to send","send"],"correct":0,"point":2,"why":{"en":"sending: 'Would you mind' takes -ing. 'To send' and 'send' don't follow mind.","tr":"sending: 'Would you mind' -ing alır. 'To send' ve 'send' mind'dan sonra gelmez.","fa":"sending درست است، چون بعد از Would you mind فعل ing‌دار می‌آید. to send و send بعد از mind نمی‌آیند."}},{"from":"hr-2-1","kind":"blank","prompt":"Every new driver ___ complete the safety course.","options":["must to","must","musts"],"correct":1,"point":2,"why":{"en":"must: must + plain verb, with no -s. 'Must to' adds to, and 'musts' is not a form.","tr":"must: must + yalın fiil; -s almaz. 'Must to' to ekler; 'musts' bir biçim değildir.","fa":"⁨must⁩ درست است: ⁨must⁩ و فعل ساده، بدون ⁨-s⁩. ⁨must to⁩ به‌اشتباه ⁨to⁩ دارد و ⁨musts⁩ شکل درستی نیست."}},{"from":"hr-2-3","kind":"blank","prompt":"Could you tell me ___ you left your last job?","options":["why did","why do","why"],"correct":2,"point":2,"why":{"en":"why: an indirect question keeps statement order, so no did or do. 'Why did' and 'why do' are question order.","tr":"why: dolaylı soru düz sırayı korur, bu yüzden did ya da do gelmez. 'Why did' ve 'why do' soru sırasıdır.","fa":"why درست است، چون سؤال غیرمستقیم ترتیب خبری دارد و did یا do نمی‌خواهد. why did و why do ترتیب سؤالی‌اند."}},{"from":"hr-3-3","kind":"blank","prompt":"She ___ us she had worked nights before.","options":["said","told","spoke"],"correct":1,"point":2,"why":{"en":"told: 'tell' takes a person (told us). 'Said' takes no person, and 'spoke' doesn't report words this way.","tr":"told: 'tell' bir kişi alır (told us). 'Said' kişi almaz; 'spoke' sözleri bu şekilde aktarmaz.","fa":"told درست است، چون tell شخص می‌خواهد (told us). بعد از said شخص نمی‌آید و spoke حرف را این‌طور نقل نمی‌کند."}},{"from":"hr-3-4","kind":"blank","prompt":"Last year every complaint ___ answered within a week.","options":["was","did","had"],"correct":0,"point":2,"why":{"en":"was: each complaint received the action last year, so was + past participle. 'Did' and 'had' don't make the passive.","tr":"was: her şikâyet geçen yıl eylemi aldı, bu yüzden was + üçüncü hâl. 'Did' ve 'had' edilgen yapı kurmaz.","fa":"was درست است، چون هر شکایت پارسال جواب داده شد و was و اسم مفعول لازم است. did و had مجهول نمی‌سازند."}},{"from":"hr-4-1","kind":"blank","prompt":"You are ___ to 30 days of paid leave.","options":["allowed","entitled","given"],"correct":1,"point":2,"why":{"en":"entitled: 'entitled to' means it is your right. 'Allowed' is permission, and 'given to' doesn't make this meaning.","tr":"entitled: 'entitled to' bunun senin hakkın olduğu demektir. 'Allowed' izindir; 'given to' bu anlamı vermez.","fa":"entitled درست است، چون entitled to یعنی حق توست. allowed یعنی اجازه و given to این معنی را نمی‌دهد."}},{"from":"hr-4-2","kind":"blank","prompt":"Please finish the course ___ Friday.","options":["until","since","by"],"correct":2,"point":2,"why":{"en":"by: 'by Friday' is a deadline. 'Until' is the whole time up to Friday, and 'since' looks back from now.","tr":"by: 'by Friday' bir son tarihtir. 'Until' cumaya kadar bütün süredir; 'since' şimdiden geriye bakar.","fa":"by درست است، چون by Friday مهلت است. until تمام مدت تا جمعه است و since از الان به عقب نگاه می‌کند."}},{"from":"hr-4-3","kind":"blank","prompt":"That sounds ___.","options":["worrying","worried","like worrying"],"correct":0,"point":2,"why":{"en":"worrying: -ing describes the situation that causes the feeling. 'Worried' is how a person feels, and 'like worrying' is not English.","tr":"worrying: -ing duyguya yol açan durumu anlatır. 'Worried' kişinin ne hissettiğidir; 'like worrying' İngilizce değildir.","fa":"⁨worrying⁩ درست است، چون ⁨-ing⁩ موقعیتی را توصیف می‌کند که آن حس را می‌سازد. ⁨worried⁩ حس آدم است و ⁨like worrying⁩ انگلیسی نیست."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
